import { useEffect, useRef, useState, type CSSProperties } from "react"

type Character = {
  name: string
  note: string
  image: string
  alt: string
  accent: string
}

const CHARACTERS: Character[] = [
  { name: "THE OBSERVER", note: "Detail hunter", image: ["data:image/webp;base64,","","","","","","","","","","","","","","","","","",""].join(""), alt: "Illustrated observer", accent: "#b9d9e8" },
  { name: "THE MUSE", note: "Poised and vivid", image: ["data:image/webp;base64,","","","","","","","","","","","","","","","","","","","","","","","",""].join(""), alt: "Illustrated woman with a flower", accent: "#e5c95c" },
  { name: "AFTER HOURS", note: "Velvet energy", image: ["data:image/webp;base64,","","","","","","","","","","","","","","","","","","","","","","","","",""].join(""), alt: "Illustrated woman against blue", accent: "#a8cbd2" },
  { name: "GHOST-SPIDER", note: "Swift and sharp", image: ["data:image/webp;base64,","","","","","","","","","","","","","","","","","","","","","","","","","","","zUfUFVBsh52QrzmbVET3P44/KoAAcE1FamZTNCjOxh2XQHooLuXNPIGo4ZJLYF+yXfuFTmXplwwFq3GVY8YalJvX3brZHP/84+m5bIvvIu8jDc3ciL8AKDN7Es0BSahkDuK6Q1TyCfKyJ7f7oHAIf3j42YAAA=="].join(""), alt: "Illustrated Ghost-Spider", accent: "#d7b2c4" },
]

export function CharacterSwitcherCard({ autoPlay = false }: { autoPlay?: boolean }) {
  const [index, setIndex] = useState(0)
  const [leaving, setLeaving] = useState(false)
  const timeoutRef = useRef<number | undefined>(undefined)
  const character = CHARACTERS[index]

  function next() {
    if (leaving) return
    setLeaving(true)
    window.clearTimeout(timeoutRef.current)
    timeoutRef.current = window.setTimeout(() => {
      setIndex((current) => (current + 1) % CHARACTERS.length)
      setLeaving(false)
    }, 120)
  }

  useEffect(() => () => window.clearTimeout(timeoutRef.current), [])

  useEffect(() => {
    if (!autoPlay) return
    const interval = window.setInterval(next, 1500)
    return () => window.clearInterval(interval)
  }, [autoPlay, index])

  return (
    <main className="csc-root">
      <style>{STYLES}</style>
      <button
        aria-label={`Current character: ${character.name}. Change character.`}
        className="csc-card"
        onClick={next}
        onKeyDown={(event) => event.key === "ArrowRight" && next()}
        style={{ "--accent": character.accent } as CSSProperties}
        type="button"
      >
        <span className="csc-index">{String(index + 1).padStart(2, "0")} / 04</span>
        <span className="csc-portrait"><img alt={character.alt} className={leaving ? "is-leaving" : ""} key={character.image} src={character.image} /><i /></span>
        <span className="csc-copy"><b>{character.name}</b><small>{character.note}</small></span>
        <span className="csc-action">Change character <span aria-hidden="true">→</span></span>
      </button>
    </main>
  )
}

const STYLES = `
.csc-root{--paper:#e9e6dc;--ink:#202025;min-height:100svh;width:100%;display:grid;place-items:center;padding:32px;background:var(--paper);color:var(--ink);font-family:Arial,Helvetica,sans-serif;box-sizing:border-box}.csc-root *{box-sizing:border-box}.csc-card{position:relative;width:clamp(220px,17vw,310px);padding:0;border:0;background:transparent;color:var(--ink);display:block;text-align:left;cursor:pointer;transform:rotate(2deg);outline:none;transition:transform .35s cubic-bezier(.2,.8,.2,1)}.csc-card:hover{transform:rotate(-1deg) translateY(-5px)}.csc-card:focus-visible{outline:2px solid var(--ink);outline-offset:9px}.csc-index{position:absolute;z-index:2;top:14px;right:12px;padding:5px 7px;border-radius:99px;background:var(--paper);font-size:.52rem;letter-spacing:.08em}.csc-portrait{position:relative;display:block;aspect-ratio:.92;overflow:hidden;border-radius:48% 52% 44% 56% / 42% 48% 52% 58%;background:var(--accent);transition:border-radius .45s}.csc-card:hover .csc-portrait{border-radius:57% 43% 53% 47% / 50% 55% 45% 50%}.csc-portrait img{width:100%;height:100%;display:block;object-fit:cover;object-position:center top;transition:transform .45s ease,opacity .12s ease}.csc-card:hover .csc-portrait img{transform:scale(1.035)}.csc-portrait img.is-leaving{opacity:0;transform:scale(1.065)}.csc-portrait i{position:absolute;inset:10px;border:1px solid color-mix(in srgb,var(--ink) 40%,transparent);border-radius:inherit}.csc-copy{display:grid;grid-template-columns:1fr auto;align-items:baseline;gap:16px;margin-top:17px;padding:0 2px 18px;border-bottom:1px solid var(--ink)}.csc-copy b{display:block;white-space:nowrap;font:700 .84rem/1 Arial,Helvetica,sans-serif;letter-spacing:.02em}.csc-copy small{display:block;margin:0;color:color-mix(in srgb,var(--ink) 72%,transparent);font:italic 400 .78rem/1 Georgia,serif}.csc-action{margin:0 2px;padding:12px 0 1px;display:flex;justify-content:space-between;align-items:center;font-size:.55rem;text-transform:uppercase;letter-spacing:.08em}.csc-action>span{font-size:1rem;line-height:1;transition:transform .2s ease}.csc-card:hover .csc-action>span{transform:translateX(3px)}.dark .csc-root{--paper:#181916;--ink:#f0eee8}.dark .csc-index{background:#242520}.dark .csc-portrait i{border-color:rgb(240 238 232 / 42%)}@media(max-width:680px){.csc-root{padding:24px 20px}.csc-card{width:min(100%,440px);display:grid;grid-template-columns:132px minmax(0,1fr);grid-template-rows:auto auto;gap:0 14px;transform:none}.csc-card:hover{transform:translateY(-3px)}.csc-portrait{grid-column:1;grid-row:1 / 3;width:132px;height:168px}.csc-index{top:7px;left:7px;right:auto}.csc-copy{grid-column:2;grid-row:1;align-self:end;margin-top:0;padding:0 0 13px}.csc-copy b{font-size:.8rem}.csc-action{grid-column:2;grid-row:2;align-self:start;margin:0;padding:11px 0 2px}}@media(max-width:390px){.csc-card{grid-template-columns:112px minmax(0,1fr)}.csc-portrait{width:112px;height:144px}}@media(prefers-reduced-motion:reduce){.csc-root *{transition-duration:.01ms!important}}
`
